    functionParameter: {
      indexNum: {
        name: "ch\u1EC9 s\u1ED1",
        detail: "D\xF9ng \u0111\u1EC3 ch\u1EC9 \u0111\u1ECBnh gi\xE1 tr\u1ECB tham s\u1ED1 \u0111\u01B0\u1EE3c ch\u1ECDn. index_num ph\u1EA3i l\xE0 m\u1ED9t s\u1ED1 t\u1EEB 1 \u0111\u1EBFn 254 ho\u1EB7c l\xE0 m\u1ED9t c\xF4ng th\u1EE9c ho\u1EB7c tham chi\u1EBFu \xF4 ch\u1EE9a m\u1ED9t s\u1ED1 t\u1EEB 1 \u0111\u1EBFn 254.\nN\u1EBFu index_num l\xE0 1, h\xE0m CHOOSE tr\u1EA3 v\u1EC1 value1; n\u1EBFu l\xE0 2, h\xE0m CHOOSE tr\u1EA3 v\u1EC1 value2, v\xE0 c\u1EE9 nh\u01B0 v\u1EADy.\nN\u1EBFu index_num nh\u1ECF h\u01A1n 1 ho\u1EB7c l\u1EDBn h\u01A1n ch\u1EC9 s\u1ED1 c\u1EE7a gi\xE1 tr\u1ECB cu\u1ED1i c\xF9ng trong danh s\xE1ch, h\xE0m CHOOSE tr\u1EA3 v\u1EC1 gi\xE1 tr\u1ECB l\u1ED7i #VALUE!\nN\u1EBFu index_num l\xE0 s\u1ED1 th\u1EADp ph\xE2n, n\xF3 s\u1EBD b\u1ECB c\u1EAFt b\u1ECF th\xE0nh s\u1ED1 nguy\xEAn tr\u01B0\u1EDBc khi s\u1EED d\u1EE5ng."
      },
      value1: {
        name: "gi\xE1 tr\u1ECB 1",
        detail: "CHOOSE s\u1EBD ch\u1ECDn m\u1ED9t gi\xE1 tr\u1ECB ho\u1EB7c h\xE0nh \u0111\u1ED9ng t\u1EEB c\xE1c gi\xE1 tr\u1ECB n\xE0y d\u1EF1a tr\xEAn index_num. Tham s\u1ED1 c\xF3 th\u1EC3 l\xE0 s\u1ED1, tham chi\u1EBFu \xF4, t\xEAn \u0111\u01B0\u1EE3c \u0111\u1ECBnh ngh\u0129a, c\xF4ng th\u1EE9c, h\xE0m ho\u1EB7c v\u0103n b\u1EA3n."
      },
      value2: { name: "gi\xE1 tr\u1ECB 2", detail: "1 \u0111\u1EBFn 254 tham s\u1ED1 gi\xE1 tr\u1ECB." }
    }
